package com.bank.flink.eo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Mimics TwoPhaseCommitSinkFunction: begin/preCommit/commit/abort.
// Output stays in a PENDING buffer and only becomes VISIBLE on commit.
class TransactionalLedgerSink {
    private static final Logger log = Logger.getLogger(TransactionalLedgerSink.class.getName());

    // committed, read-committed visible store: settlementId -> amount
    private final Map<String, Settlement> committedLedger = new LinkedHashMap<>();
    // current open transaction's buffered output
    private List<Settlement> pending = new ArrayList<>();
    private boolean preCommitted = false;

    void beginTransaction() {
        pending = new ArrayList<>();
        preCommitted = false;
        log.info(() -> "beginTransaction: new external transaction opened");
    }

    void write(Settlement s) {
        pending.add(s); // buffered into the open transaction, NOT visible yet
    }

    // Called when the checkpoint barrier reaches the sink: flush+prepare, no commit.
    void preCommit() {
        preCommitted = true;
        log.info(() -> "preCommit: " + pending.size()
                + " records flushed to transaction, NOT yet visible");
    }

    // Called only after checkpoint is CONFIRMED complete: make visible.
    void commit() {
        if (!preCommitted) {
            log.warning(() -> "commit called without preCommit - ignoring");
            return;
        }
        for (Settlement s : pending) {
            committedLedger.putIfAbsent(s.getSettlementId(), s); // idempotent by id
        }
        log.info(() -> "commit: " + pending.size()
                + " records now VISIBLE. ledger size=" + committedLedger.size());
        pending = new ArrayList<>();
        preCommitted = false;
    }

    // Called on failure before commit: throw away the uncommitted transaction.
    void abort() {
        log.severe(() -> "abort: discarding " + pending.size() + " uncommitted records");
        pending = new ArrayList<>();
        preCommitted = false;
    }

    Map<String, Settlement> getCommittedLedger() { return committedLedger; }
}
