package com.bank.flink.eo;

import java.util.logging.Logger;

// Drives the checkpoint-coupled transaction lifecycle of the 2PC sink.
class CheckpointDriver {
    private static final Logger log = Logger.getLogger(CheckpointDriver.class.getName());

    private final TransactionalLedgerSink sink;

    CheckpointDriver(TransactionalLedgerSink sink) {
        this.sink = sink;
    }

    // A full successful checkpoint cycle.
    void runCheckpointCycle(Settlement[] batch) {
        sink.beginTransaction();
        for (Settlement s : batch) sink.write(s);
        sink.preCommit();          // barrier reaches sink
        // ... JobManager confirms checkpoint complete ...
        sink.commit();             // only now visible
    }

    // A crash AFTER preCommit but BEFORE commit, then recovery replays.
    void runCrashThenRecover(Settlement[] batch) {
        sink.beginTransaction();
        for (Settlement s : batch) sink.write(s);
        sink.preCommit();
        log.severe(() -> "*** CRASH before checkpoint confirmed ***");
        sink.abort();              // uncommitted transaction rolled back

        // RECOVERY: Flink rewinds source, replays the SAME batch, commits once.
        log.info(() -> "--- recovery: replay from last checkpoint ---");
        sink.beginTransaction();
        for (Settlement s : batch) sink.write(s);
        sink.preCommit();
        sink.commit();             // committed exactly once (no duplicates)
    }
}
