package com.bank.flink.eo;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: a clean checkpoint commits once; a crash after preCommit
// aborts and replays without creating duplicates.
public class ExactlyOnceDemo {
    private static final Logger log = Logger.getLogger(ExactlyOnceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new EoLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransactionalLedgerSink sink = new TransactionalLedgerSink();
        CheckpointDriver driver = new CheckpointDriver(sink);

        Settlement[] batch1 = {
            new Settlement("STL-1", "SAV2001", new BigDecimal("1000")),
            new Settlement("STL-2", "CUR3001", new BigDecimal("500"))
        };
        Settlement[] batch2 = {
            new Settlement("STL-3", "SAV2001", new BigDecimal("250"))
        };

        log.info(() -> "=== Clean checkpoint cycle ===");
        driver.runCheckpointCycle(batch1);

        log.info(() -> "=== Crash after preCommit, then recovery ===");
        driver.runCrashThenRecover(batch2);

        log.info(() -> "FINAL committed ledger = " + sink.getCommittedLedger().keySet()
                + " (each settlement exactly once)");
    }
}

// ─── Would be in EoLogFormatter.java in a real project ───
class EoLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
